    ('uk_menu_code', 'sys_menu_permission', 'UNIQUE (menu_code)'),
    ('uk_role_code', 'sys_role', 'UNIQUE (role_code)'),
    ('uk_role_file', 'sys_role_file_permission', 'UNIQUE (role_id, file_permission_id)'),
    ('uk_role_menu', 'sys_role_menu_permission', 'UNIQUE (role_id, menu_permission_id)'),
